  x=x*2 if side=='left' else (x-50)*2
  text=e(row['label']);research=visual_v2.RESEARCH.get(row['sic'])
  s+=f'<div class="label" data-sic="{row["sic"]}" style="--x:{x}%;--y:{y}%"><span>{text}</span>'
