manifest={'baseline_commit':'0cb07c2e78ccb16240c799b31cd62736e2135529','previous_A_commit':'034e87735873db441ad2a247f013b8457058262e','baseline':'Actual anonymous visual_v2.render output, unchanged except local asset URLs; no app server, identity fixture or data record needed','artwork':'../assets/uk-economy.webp','artwork_sha256':hashlib.sha256((D.parent/'assets/uk-economy.webp').read_bytes()).hexdigest(),'original_labels':{r['sic']:{'label':r['label'],'position':r['position']} for r in basis['districts']},'scope':'UK economy / original 20 sectors; no new research or relationship data'}
